// Keeps only the fields needed for ISO 690 and BibTeX.
const pick = (m) => ({
  doi: m.DOI ?? null, type: m.type ?? null, title: m.title?.[0] ?? null,
  authors: (m.author ?? []).map((a) => ({ family: a.family ?? a.name ?? null, given: a.given ?? null })),
  year: m.issued?.['date-parts']?.[0]?.[0] ?? null, container: m['container-title']?.[0] ?? null,
  volume: m.volume ?? null, issue: m.issue ?? null, pages: m.page ?? null, publisher: m.publisher ?? null, url: m.URL ?? null,
  retracted: (m['update-to'] ?? []).some((u) => u.type === 'retraction'),
});
const msg = $input.first().json?.message;
if (!msg || typeof msg !== 'object') return [{ json: { found: false, query: $('Start').first().json } }];
const works = Array.isArray(msg.items) ? msg.items.map(pick) : [pick(msg)];
return [{ json: { found: works.length > 0, works } }];
